@@ -0,0 +1,45 @@
+import { EventEmitter } from 'events';
+
+class NotificationService extends EventEmitter {
+  private listeners = new Map<string, Set<Function>>();
+
+  subscribe(candidateId: string, handler: Function) {
+    if (!this.listeners.has(candidateId)) {
+      this.listeners.set(candidateId, new Set());
+    }
+    this.listeners.get(candidateId)!.add(handler);
+    this.on(candidateId, handler as any);
+  }
+
+  unsubscribe(candidateId: string, handler: Function) {
+    this.listeners.get(candidateId)?.delete(handler);
+    this.off(candidateId, handler as any);
+  }
+
+  notify(candidateId: string, event: unknown) {
+    this.emit(candidateId, event);
+  }
+}
+
+export const notifications = new NotificationService();
